"""Strict source contracts and graph mutations generated by deterministic adapters."""

import hashlib
import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Literal
from urllib.parse import quote

from pydantic import BaseModel, ConfigDict, Field, field_validator

from knowledge.ontology import validate_edge, validate_node


def digest(value) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest()


def entity_id(namespace, label, *parts):
    return ":".join(quote(str(p), safe="-_.") for p in (namespace, label.lower(), *parts))


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class Source(StrictModel):
    id: str = Field(pattern=r"^[a-zA-Z0-9_.-]{1,80}$")
    adapter: Literal["catalog", "deployments", "logs", "incidents", "otlp"]
    path: Path
    environment: str = Field(pattern=r"^[a-zA-Z0-9_.-]{1,80}$")


class Sources(StrictModel):
    namespace: str = Field(pattern=r"^inputs-[a-zA-Z0-9_.-]{1,80}$")
    sources: list[Source] = Field(min_length=1, max_length=32)

    @field_validator("sources")
    @classmethod
    def unique_ids(cls, values):
        if len({s.id for s in values}) != len(values):
            raise ValueError("Source IDs must be unique.")
        return values

    @classmethod
    def load(cls, path: Path):
        config = cls.model_validate_json(path.read_text())
        for source in config.sources:
            source.path = (path.resolve().parent / source.path).resolve()
        return config


@dataclass
class Node:
    label: str
    id: str
    properties: dict

    def __post_init__(self):
        validate_node(self.label, self.properties)


@dataclass
class Edge:
    kind: str
    source: str
    target: str
    source_label: str
    target_label: str
    properties: dict

    def __post_init__(self):
        validate_edge(self.kind, self.source_label, self.target_label)


@dataclass
class Mutation:
    nodes: list[Node] = field(default_factory=list)
    edges: list[Edge] = field(default_factory=list)
    catalog_at: int | None = None
    warnings: list[str] = field(default_factory=list)
